DROP TABLE IF EXISTS `scenic_spot`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `scenic_spot` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `city_id` int NOT NULL COMMENT '关联城市ID（外键，对应scenic_city表id）',
  `district` varchar(50) NOT NULL COMMENT '区县（对应Excel「区县」列）',
  `spot_name` varchar(100) NOT NULL COMMENT '景点名称（对应Excel「名称」列）',
  `score` decimal(3,1) NOT NULL COMMENT '游客评分（对应Excel「评分」列）',
  `ticket_price` decimal(8,2) NOT NULL COMMENT '门票价格（对应Excel「价格」列）',
  `sales_volume` decimal(10,2) NOT NULL COMMENT '线上销量（对应Excel「销量」列）',
  `coordinate` varchar(50) NOT NULL COMMENT '坐标文本（对应Excel「坐标」列）',
  `spot_intro` text NOT NULL COMMENT '景点简介（对应Excel「简介」列）',
  `address` varchar(255) NOT NULL COMMENT '详细地址（对应Excel「具体地址」列）',
  `longitude` decimal(10,6) NOT NULL COMMENT '景点经度（对应Excel「经度」列）',
  `latitude` decimal(10,6) NOT NULL COMMENT '景点纬度（对应Excel「纬度」列）',
  `spot_type` varchar(50) NOT NULL COMMENT '景点类型（对应Excel「景点类型」列）',
  `star_level` tinyint NOT NULL COMMENT '星级编码（对应Excel「星级_编码」列）',
  PRIMARY KEY (`id`),
  KEY `fk_city_id` (`city_id`),
  CONSTRAINT `fk_scenic_city` FOREIGN KEY (`city_id`) REFERENCES `scenic_city` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=679 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='旅游景点核心数据表';
/*!40101 SET character_set_client = @saved_cs_client */;

